                m2.map(function (m) { return '• ' + String(m.concern || '').trim() + ' -> ' + String(m.effect || '').trim() + ' -> ' + String(m.mitigationOrGap || '').trim(); }).join('\n');
            let mitigation = String(x.mitigation || '').trim();
