            kind: 'hfAlerts', idField: 'alertId', render: 'renderAlerts',
            std: '§25.1322 flight-crew alerting — priority and sensory modality vocabularies',
            fields: ['name', 'priority', 'modality', 'fcIds', 'notes'],
