            g.flagged.slice(0, 8).forEach(function (f) { rows += '<div style="font-size:11.5px;color:' + sub + ';padding:2px 0 0 10px;">⚠ ' + _esc(String(f.id)) + ' — ' + _esc(f.issues.join('; ')) + '</div>'; });
