            const js = o.judge ? (o.judge.credibility + 'c/' + o.judge.terseness + 't/' + o.judge.purity + 'p') : '—';
            body += '<div style="padding:8px 0;border-top:1px solid ' + bd + ';font-size:12.5px;">'
