                const out = await _runSafetyVerifier({ kind: crit.some(function (a) { return a.op === 'add_fta_tree'; }) ? 'fta' : 'fha', draft: crit, context: { certBasis: (typeof _certBasis === 'function' ? _certBasis() : '') } });
